-- LAB-F DRIFT SENTINEL: PRODUCTION EXPORT (SELECT only, read-only).
-- Generated by sportsassets.lab.drift_runner --export-sql from the
-- SAME SELECT statements the read-only endpoint runs
-- (sportsassets/lab/drift_reads.py), with literal arguments:
--   clock 1791145620.0, since 1789936020.0, ref_max_s 604800.0, cmp_max_s 259200.0.
-- Output rows: LABDRIFT|<source>#cols|[names], then one
-- LABDRIFT|<source>|[values] per row; the parser
-- (drift_runner --from-log) applies point_in_time() and the pure
-- sentinel exactly as the endpoint does. Bounded by LIMITs.

\echo === LABDRIFT relations present
SELECT 'LABDRIFT|meta|' || json_build_object('clock', 1791145620.0, 'since', 1789936020.0, 'ref_max_s', 604800.0, 'cmp_max_s', 259200.0)::text AS line;
SELECT 'LABDRIFT|relations|' || json_object_agg(k, v)::text AS line FROM (VALUES ('decisions', to_regclass('paper_decisions') IS NOT NULL), ('orders', to_regclass('paper_orders') IS NOT NULL), ('fills', to_regclass('paper_fills') IS NOT NULL), ('eddie', to_regclass('eddie_execution_outcomes') IS NOT NULL), ('econ', to_regclass('pos_position_economics') IS NOT NULL), ('sleeves', to_regclass('paper_sleeve_classifications') IS NOT NULL), ('settlements', to_regclass('paper_settlements') IS NOT NULL), ('canonical_executions', to_regclass('canonical_intent_executions') IS NOT NULL), ('execmirror_orders', to_regclass('execmirror_orders') IS NOT NULL), ('execmirror_fills', to_regclass('execmirror_fills') IS NOT NULL), ('bettor_funded_fills', to_regclass('bettor_funded_fills') IS NOT NULL), ('kalshi_live_fills', to_regclass('kalshi_live_fills') IS NOT NULL)) AS r(k, v);
\echo === LABDRIFT decisions
SELECT 'LABDRIFT|decisions#cols|' || (SELECT json_agg(e.key) FROM json_each(row_to_json(q)) e)::text AS line FROM (WITH v AS (     SELECT d.strategy, d.policy_version, d.policy_decision->'parameters'->>'version_id' AS pv,            min(d.decided_at) AS first_at       FROM paper_decisions d      WHERE d.decided_at <= to_timestamp(1791145620.0)        AND d.recorded_at <= to_timestamp(1791145620.0)      GROUP BY 1, 2, 3 ), latest AS (     SELECT DISTINCT ON (d.strategy) d.strategy, d.policy_version,            d.policy_decision->'parameters'->>'version_id' AS pv       FROM paper_decisions d      WHERE d.decided_at <= to_timestamp(1791145620.0)        AND d.recorded_at <= to_timestamp(1791145620.0)      ORDER BY d.strategy, d.decided_at DESC, d.decision_id DESC ) SELECT d.decision_id, d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8 AS recorded_at,        d.verdict, d.refusal, d.us_market_slug, d.holding_side,        d.fixture, d.label->>'competition' AS competition,        d.label->>'market_type' AS market_type, ev.sport_family,        d.policy_decision->>'gross_edge_pp' AS gross_edge_pp,        d.economics->'acquisition'->>'expected_net_profit_usd'            AS net_ev_usd,        d.economics->'acquisition'->>'qty' AS acq_qty,        d.pinnacle->>'at' AS pin_at,        d.pinnacle->>'received_at' AS pin_received_at,        d.pinnacle->>'age_s' AS pin_age_s,        d.pinnacle->>'provider' AS pin_provider,        d.book->>'age_at_decision_s' AS book_age_s   FROM paper_decisions d   JOIN v ON v.strategy = d.strategy         AND v.policy_version = d.policy_version         AND v.pv IS NOT DISTINCT FROM (d.policy_decision->'parameters'->>'version_id')   JOIN latest l ON l.strategy = d.strategy         AND l.policy_version = d.policy_version         AND l.pv IS NOT DISTINCT FROM (d.policy_decision->'parameters'->>'version_id')   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)    AND ((d.decided_at >= v.first_at          AND d.decided_at < v.first_at                             + make_interval(secs => 604800.0::float8))         OR d.decided_at >= to_timestamp(1791145620.0)                            - make_interval(secs => 259200.0::float8))  ORDER BY d.decided_at, d.decision_id  LIMIT 50000) q LIMIT 1;
SELECT 'LABDRIFT|decisions|' || (SELECT json_agg(e.value) FROM json_each(row_to_json(q)) e)::text AS line FROM (WITH v AS (     SELECT d.strategy, d.policy_version, d.policy_decision->'parameters'->>'version_id' AS pv,            min(d.decided_at) AS first_at       FROM paper_decisions d      WHERE d.decided_at <= to_timestamp(1791145620.0)        AND d.recorded_at <= to_timestamp(1791145620.0)      GROUP BY 1, 2, 3 ), latest AS (     SELECT DISTINCT ON (d.strategy) d.strategy, d.policy_version,            d.policy_decision->'parameters'->>'version_id' AS pv       FROM paper_decisions d      WHERE d.decided_at <= to_timestamp(1791145620.0)        AND d.recorded_at <= to_timestamp(1791145620.0)      ORDER BY d.strategy, d.decided_at DESC, d.decision_id DESC ) SELECT d.decision_id, d.strategy, d.policy_version,        d.policy_decision->'parameters'->>'version_id' AS param_version_id,        extract(epoch FROM d.decided_at)::float8 AS t,        extract(epoch FROM d.recorded_at)::float8 AS recorded_at,        d.verdict, d.refusal, d.us_market_slug, d.holding_side,        d.fixture, d.label->>'competition' AS competition,        d.label->>'market_type' AS market_type, ev.sport_family,        d.policy_decision->>'gross_edge_pp' AS gross_edge_pp,        d.economics->'acquisition'->>'expected_net_profit_usd'            AS net_ev_usd,        d.economics->'acquisition'->>'qty' AS acq_qty,        d.pinnacle->>'at' AS pin_at,        d.pinnacle->>'received_at' AS pin_received_at,        d.pinnacle->>'age_s' AS pin_age_s,        d.pinnacle->>'provider' AS pin_provider,        d.book->>'age_at_decision_s' AS book_age_s   FROM paper_decisions d   JOIN v ON v.strategy = d.strategy         AND v.policy_version = d.policy_version         AND v.pv IS NOT DISTINCT FROM (d.policy_decision->'parameters'->>'version_id')   JOIN latest l ON l.strategy = d.strategy         AND l.policy_version = d.policy_version         AND l.pv IS NOT DISTINCT FROM (d.policy_decision->'parameters'->>'version_id')   LEFT JOIN external_valuations ev ON ev.id = d.valuation_id  WHERE d.decided_at <= to_timestamp(1791145620.0)    AND d.recorded_at <= to_timestamp(1791145620.0)    AND ((d.decided_at >= v.first_at          AND d.decided_at < v.first_at                             + make_interval(secs => 604800.0::float8))         OR d.decided_at >= to_timestamp(1791145620.0)                            - make_interval(secs => 259200.0::float8))  ORDER BY d.decided_at, d.decision_id  LIMIT 50000) q WHERE q.t >= -1e+18 AND q.t < 1790985600.0;
